// Bundles src/ into the main.js that Obsidian loads.
//   node esbuild.config.mjs              watch mode, rebuilds on change (npm run dev)
//   node esbuild.config.mjs production   one build, no source map (npm run build)
import esbuild from 'esbuild';
import { builtinModules } from 'node:module';

const production = process.argv[2] === 'production';

const banner = `/*
 * Vimoase, by mandre1899 (https://github.com/mandre1899/VimOase)
 * Generated from src/ by esbuild. Do not edit this file: change src/ and run \`npm run build\`.
 */`;

const context = await esbuild.context({
  banner: { js: banner },
  entryPoints: ['src/main.ts'],
  outfile: 'main.js',
  bundle: true,
  format: 'cjs',
  target: 'es2020',
  platform: 'browser',
  // Provided by Obsidian at runtime.
  external: ['obsidian', 'electron', '@codemirror/*', '@lezer/*', ...builtinModules],
  sourcemap: production ? false : 'inline',
  treeShaking: true,
  logLevel: 'info',
});

if (production) {
  await context.rebuild();
  await context.dispose();
} else {
  await context.watch();
}
